func TestSlugify(t *testing.T) {
	t.Parallel()

	assert.Equal(t, "add-rate-limiting", slugify("Add Rate Limiting!"))
	assert.Equal(t, "eng-142", slugify("ENG-142"))
	assert.Empty(t, slugify("  --  "))
